def tr(uz, ru, en):
    return {"uz": uz, "ru": ru, "en": en}


def lesson(code, start, end, mode, title, observation, theory, task, ready, related, floor=0):
    return dict(code=code, start=start, end=end, mode=mode, title=title,
                observation=observation, theory=theory, task=task, ready=ready,
                related=related, floor=floor)


